CREATE TABLE IF NOT EXISTS members (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, pin_salt TEXT NOT NULL, pin_hash TEXT NOT NULL, is_admin INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, member_id INTEGER NOT NULL REFERENCES members(id), expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', assigned_to INTEGER NOT NULL REFERENCES members(id), weekdays TEXT NOT NULL DEFAULT '0,1,2,3,4,5,6', start_date TEXT NOT NULL, end_date TEXT, at_time TEXT NOT NULL DEFAULT '20:00', reminder_minutes INTEGER NOT NULL DEFAULT 30, points INTEGER NOT NULL DEFAULT 10, active INTEGER NOT NULL DEFAULT 1, created_by INTEGER REFERENCES members(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS occurrences (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL REFERENCES tasks(id), day TEXT NOT NULL, assigned_to INTEGER NOT NULL REFERENCES members(id), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','done')), completed_by INTEGER REFERENCES members(id), completed_at TEXT, UNIQUE(task_id,day));
CREATE INDEX IF NOT EXISTS occ_day ON occurrences(day);
CREATE INDEX IF NOT EXISTS occ_user ON occurrences(assigned_to,day);
CREATE TABLE IF NOT EXISTS push_subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT, member_id INTEGER NOT NULL REFERENCES members(id), endpoint TEXT NOT NULL UNIQUE, subscription_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_log (occurrence_id INTEGER NOT NULL REFERENCES occurrences(id), kind TEXT NOT NULL, sent_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (occurrence_id,kind));
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id INTEGER REFERENCES members(id), action TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
